using NUnit.Framework; using UnityEngine; using UnityEngine.XR.Interaction.Toolkit;
namespace Ghost.VRHandInteraction.Tests { public class PepperPickingUnitTests { [Test] public void NewPepperStartsAttached(){var go=new GameObject("Pepper");try{var m=new GameObject("Manager").AddComponent<XRInteractionManager>();var p=go.AddComponent<VRPepperPickable>();p.Configure(m);Assert.AreEqual(PepperPickState.Attached,p.State);}finally{Object.DestroyImmediate(go);}} [Test] public void ManagerDoesNotRegisterTreeRoot(){var tree=new GameObject("Tree");try{var m=tree.AddComponent<PepperPickingManager>();m.treeRoot=tree.transform;m.RegisterAll();Assert.AreEqual(0,m.TotalPepperCount);}finally{Object.DestroyImmediate(tree);}} } }
